import {recommend} from './lastplanner-intelligence.mjs';
import {diasHabiles} from './lastplanner-model.mjs';
export function resourceAssistant(form,initial={}){
 form.dataset.resourceAssistant='true';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),work=form.querySelector('[data-step="0"]'),plan=form.querySelector('[data-step="2"] details');
 const block=document.createElement('details');block.innerHTML=`<summary>Partida y superficie de referencia</summary><label>Partida confirmada por el supervisor<input data-part-name value="${esc(initial.partida?.name||'')}"></label><label>Superficie pertinente<select data-family><option value="">Sin clasificar</option>${['muros','cielos','pavimentos'].map(v=>`<option ${v===initial.partida?.family?'selected':''}>${v}</option>`).join('')}</select></label><p>Esta clasificación orienta la selección; no selecciona superficies automáticamente.</p>`;work.append(block);
 const box=document.createElement('div');box.innerHTML=`<label>Base del rendimiento<select data-rate-basis>${['persona-dia','persona-hora','cuadrilla-dia','cuadrilla-hora'].map(v=>`<option value="${v}" ${v===initial.basis?'selected':''}>${v.replace('-dia',' por día').replace('-hora',' por hora')}</option>`).join('')}</select></label><label>Unidad del rendimiento<input data-rate-unit value="${esc(initial.unit||form.elements.unidad.value)}"></label><label>Horas efectivas por día (solo rendimientos horarios)<input type="number" min="0" max="24" step="any" data-hours value="${esc(initial.hours||'')}"></label><label>Cuadrillas previstas<input data-planned-crews type="number" min="0" step="1" value="${esc(initial.plannedCrews??'')}"></label><label>Composición de una cuadrilla: rol y cantidad, una línea por rol<textarea data-crew placeholder="Rol: cantidad">${esc((initial.crew||[]).map(r=>r.role+': '+r.count).join('\n'))}</textarea></label><label>Fuente / condiciones del rendimiento provisional<textarea data-rate-source>${esc(initial.source||'')}</textarea></label><p data-recommendation role="status"></p>`;plan.append(box);
 const read=()=>({version:1,people:form.elements.dotacion.value===''?null:Number(form.elements.dotacion.value),plannedCrews:box.querySelector('[data-planned-crews]').value===''?null:Number(box.querySelector('[data-planned-crews]').value),partida:{name:block.querySelector('[data-part-name]').value.trim(),family:block.querySelector('[data-family]').value},basis:box.querySelector('[data-rate-basis]').value,unit:box.querySelector('[data-rate-unit]').value.trim(),rate:Number(form.elements.rendimientoPlan.value)||null,hours:Number(box.querySelector('[data-hours]').value)||null,crew:box.querySelector('[data-crew]').value.split('\n').filter(v=>v.trim()).map(v=>{const i=v.lastIndexOf(':');return {role:i<0?'':v.slice(0,i).trim(),count:i<0?0:Number(v.slice(i+1))};}),source:box.querySelector('[data-rate-source]').value.trim(),status:'provisional',calendar:'lunes-viernes-sin-feriados-configurados'});
 function update(){
  const v=read(),days=diasHabiles(form.elements.inicioPlan.value,form.elements.finPlan.value),byCrew=v.basis.startsWith('cuadrilla'),hourly=v.basis.endsWith('hora');
  box.querySelector('[data-hours]').closest('label').hidden=!hourly;box.querySelector('[data-crew]').closest('label').hidden=!byCrew;box.querySelector('[data-planned-crews]').closest('label').hidden=!byCrew;
  form.elements.rendimientoPlan.closest('label').firstChild.textContent='Rendimiento ('+v.basis+')';
  const result=v.partida.name?recommend({...v,quantity:Number(form.elements.cantidad.value),unit:form.elements.unidad.value,rateUnit:v.unit,days}):{state:'unavailable',message:'Confirma la partida para simular los recursos necesarios.'};
  const units=byCrew?v.plannedCrews:form.elements.dotacion.value===''?null:Number(form.elements.dotacion.value),capacity=units==null?null:units*(result.perResource||0),quantity=Number(form.elements.cantidad.value);
  box.querySelector('[data-recommendation]').textContent=result.state==='unavailable'?result.message:`SIMULACIÓN PROVISIONAL · ${result.label} (${result.people} personas). ${result.message}. Fuente: ${v.source}. ${capacity==null?'Indica la dotación propuesta para comparar capacidad.':`Con ${units} ${byCrew?'cuadrillas':'personas'} previstas: capacidad aproximada ${capacity} ${form.elements.unidad.value}. ${capacity<quantity?'Déficit frente al compromiso: '+(quantity-capacity)+' '+form.elements.unidad.value+'.':''}`} Calendario base lunes a viernes, sin feriados configurados.`;
  form.querySelector('[data-wizard-capacity]').hidden=true;
  const review=form.querySelectorAll('.lpWizardReview')[2]||form.querySelector('[data-step="3"]');let summary=review.querySelector('[data-resource-review]');if(!summary){summary=document.createElement('p');summary.dataset.resourceReview='';review.append(summary);}summary.textContent=box.querySelector('[data-recommendation]').textContent;
 }
 form.addEventListener('input',update);form.addEventListener('change',update);form.addEventListener('click',()=>queueMicrotask(update));update();return {read};
}
